                         idempotency_key, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, 0, ?, ?)`,
    ).run(id, submission.input, submission.steps, submission.failAttempts, submission.idempotencyKey, now, now);
    return { kind: 'created', row: selectById(id)! };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different submission.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
}

function listJobs(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  sendJson(res, 200, { jobs: rows.map(toJob) });
}

function getJob(res: ServerResponse, id: string): void {
  const row = selectById(id);
  if (!row) {
    sendError(res, 404, 'not_found', `No job with id ${id}.`);
    return;
  }
  sendJson(res, 200, toJob(row));
}

function health(res: ServerResponse): void {
  const hb = db.prepare("SELECT value FROM meta WHERE key = 'worker_heartbeat'").get() as unknown as { value: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.value < HEARTBEAT_FRESH_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    return method === 'GET' ? health(res) : methodNotAllowed(res, 'GET');
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return listJobs(res);
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    return getJob(res, id);
  }
  sendError(res, 404, 'not_found', `No route for ${method} ${pathname}.`);
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
